using System;using System.Globalization;using System.Linq;using ForteMove.Models.Common;using ForteMove.Models.Operations;using ForteMove.Models.Scheduling;using ForteMove.Web.Infrastructure;
namespace ForteMove.Web.Driver{public partial class TripDetailsPage:DriverPage{private long Id{get{long id;return long.TryParse(Request.QueryString["id"],out id)?id:0;}}protected void Page_Load(object sender,EventArgs e){if(!IsPostBack)Bind();}private void Bind(){DriverTripDetails d=ServiceFactory.CreateDriverOperationsService().GetTripDetails(CurrentPrincipalContext.UserAccountId,Id);if(d==null){Response.Redirect(ResolveUrl("~/Driver/Today.aspx"),true);return;}lnkFuel.NavigateUrl=ResolveUrl("~/Driver/Fuel/RequestFuel.aspx?id="+Id);lnkFuel.Visible=ForteMove.Business.Fuel.FuelPolicy.Eligible(ServiceFactory.CreateDriverFuelService().GetTrip(Id,CurrentPrincipalContext.UserAccountId));litTripCode.Text=Server.HtmlEncode(d.TripCode);litRoute.Text=Server.HtmlEncode(d.RouteCode+" · "+d.RouteName);litDate.Text=d.ServiceDate.ToString("dddd, dd MMMM yyyy",CultureInfo.CurrentCulture);litDeparture.Text=d.ScheduledDepartureTime.ToString("hh\\:mm");litBus.Text=Server.HtmlEncode(d.FleetNumber);litStatus.Text=Server.HtmlEncode(d.Status.ToString().Replace("InProgress","In progress"));litJourney.Text=Server.HtmlEncode(d.OriginName+" to "+d.DestinationName);rptStops.DataSource=d.StopNames;rptStops.DataBind();hidTripRv.Value=Token(d.TripRowVersion);hidAssignmentRv.Value=Token(d.AssignmentRowVersion);hidExecutionRv.Value=Token(d.Execution==null?null:d.Execution.RowVersion);hidBusRv.Value=Token(d.BusRowVersion);pnlTimes.Visible=d.Execution!=null;if(d.Execution!=null){litActualStart.Text=FormatOperationalTime(d.Execution.ActualStartUtc);litActualCompletion.Text=d.Execution.ActualCompletionUtc.HasValue?FormatOperationalTime(d.Execution.ActualCompletionUtc.Value):"Not completed";}bool blocked=d.OpenCannotProceed!=null||d.HasUnresolvedCriticalDefect||d.RequiresReview;pnlBlocked.Visible=blocked;if(d.OpenCannotProceed!=null)litBlocked.Text="A Cannot Proceed report is awaiting administrator resolution.";else if(d.HasUnresolvedCriticalDefect)litBlocked.Text="A Critical bus defect must be resolved before this Trip can start or resume.";else if(d.RequiresReview)litBlocked.Text="This Trip requires administrator review.";bool preStart=d.Execution==null&&(d.Status==TripStatus.Scheduled||d.Status==TripStatus.Ready||d.Status==TripStatus.Delayed);lnkReadiness.Visible=preStart&&d.CurrentInspection==null&&!blocked;btnStart.Visible=!blocked&&d.CurrentInspection!=null&&d.Execution==null&&(d.Status==TripStatus.Ready||d.Status==TripStatus.Delayed);btnResume.Visible=!blocked&&d.Execution!=null&&d.Status==TripStatus.Delayed;lnkDelay.Visible=!blocked&&(d.Status==TripStatus.Scheduled||d.Status==TripStatus.Ready||d.Status==TripStatus.InProgress);lnkComplete.Visible=!blocked&&d.Execution!=null&&(d.Status==TripStatus.InProgress||d.Status==TripStatus.Delayed);lnkCannotProceed.Visible=d.OpenCannotProceed==null&&(d.Status!=TripStatus.Completed&&d.Status!=TripStatus.Cancelled);lnkDefect.Visible=d.Status!=TripStatus.Cancelled;lnkReadiness.NavigateUrl=Url("PreTripCheck.aspx");lnkDelay.NavigateUrl=Url("ReportDelay.aspx");lnkComplete.NavigateUrl=Url("CompleteTrip.aspx");lnkCannotProceed.NavigateUrl=Url("CannotProceed.aspx");lnkDefect.NavigateUrl=Url("ReportDefect.aspx");rptStatusHistory.DataSource=d.StatusHistory;rptStatusHistory.DataBind();pnlHistory.Visible=d.StatusHistory.Count>0;}protected void btnStart_Click(object sender,EventArgs e){Run(ServiceFactory.CreateDriverOperationsService().StartTrip(ActionRequest(),CurrentPrincipalContext.UserAccountId),"Trip started.");}protected void btnResume_Click(object sender,EventArgs e){Run(ServiceFactory.CreateDriverOperationsService().ResumeTrip(ActionRequest(),CurrentPrincipalContext.UserAccountId),"Trip resumed.");}private TripOperationRequest ActionRequest(){return new TripOperationRequest{TripId=Id,TripRowVersion=Parse(hidTripRv.Value),AssignmentRowVersion=Parse(hidAssignmentRv.Value),RelatedRowVersion=Parse(hidExecutionRv.Value)};}private void Run(ServiceResult<bool> result,string success){pnlMessage.CssClass=result.Succeeded?"alert alert-success":"alert alert-danger";litMessage.Text=Server.HtmlEncode(result.Succeeded?success:string.Join(" ",result.Errors.Select(x=>x.Message)));pnlMessage.Visible=true;Bind();}private string Url(string page){return ResolveUrl("~/Driver/"+page+"?id="+Id.ToString(CultureInfo.InvariantCulture));}protected string FormatOperationalTime(object utc){if(utc==null)return string.Empty;return ServiceFactory.CreateDriverOperationsService().ToOperationalTime(Convert.ToDateTime(utc)).ToString("dd MMM yyyy HH:mm",CultureInfo.CurrentCulture);}protected string FormatHistoryStatus(object value){return Convert.ToString(value).Replace("InProgress","In progress");}private static string Token(byte[] value){return value==null?string.Empty:Convert.ToBase64String(value);}private static byte[] Parse(string value){try{return Convert.FromBase64String(value);}catch{return null;}}}}
